#!/usr/bin/env python3
"""Render deterministic Markdown from a QA milestone evidence manifest."""

from __future__ import annotations

import argparse
import json
from pathlib import Path
import sys


def render(manifest: dict) -> str:
    milestone = manifest.get("milestone", "unknown")
    environment = json.dumps(manifest.get("environment", {}), indent=2, sort_keys=True)
    lines = [
        f"# {milestone} Evidence Summary",
        "",
        "_Generated by `scripts/qa-generate-evidence-summary.py`; do not edit by hand._",
        "",
        f"- Result: `{manifest.get('result', 'unknown')}`",
        f"- Tested commit: `{manifest.get('repository_commit', 'unknown')}`",
        f"- Started: `{manifest.get('started_at', 'unknown')}`",
        f"- Finished: `{manifest.get('finished_at', 'unknown')}`",
        "",
        "## Environment",
        "",
        "```json",
        environment,
        "```",
        "",
        "## Commands",
        "",
    ]
    commands = manifest.get("commands", [])
    lines.extend(f"{index}. `{command.replace('`', '``')}`" for index, command in enumerate(commands, 1))
    lines.extend(["", "## Limitations", ""])
    limitations = manifest.get("limitations", [])
    lines.extend(f"- {limitation}" for limitation in limitations)
    if not limitations:
        lines.append("_None recorded._")
    lines.extend([
        "",
        "## Hashed artifacts",
        "",
        "| Path | SHA-256 |",
        "|---|---|",
    ])
    for artifact in manifest.get("artifacts", []):
        lines.append(f"| `{artifact.get('path', '')}` | `{artifact.get('sha256', '')}` |")
    lines.append("")
    return "\n".join(lines)


def main() -> int:
    parser = argparse.ArgumentParser()
    parser.add_argument("--manifest", default="-", help="manifest path, or - for stdin")
    parser.add_argument("--output", help="write to this path instead of stdout")
    args = parser.parse_args()
    try:
        source = sys.stdin.read() if args.manifest == "-" else Path(args.manifest).read_text()
        manifest = json.loads(source)
    except (OSError, json.JSONDecodeError) as exc:
        print(f"error: read manifest: {exc}", file=sys.stderr)
        return 2
    generated = render(manifest)
    if args.output:
        Path(args.output).write_text(generated)
    else:
        sys.stdout.write(generated)
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
